p='src/server/jobs/overdue-issue-job.ts'
s=open(p).read()
def rep(old,new):
    global s
    assert s.count(old)==1, old[:60]
    s=s.replace(old,new)
rep('''import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

/** How many organizations one pass sweeps. */
const ORG_BATCH = 50;
''','''import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { OrgId } from "@/types/common";
import type { JobResult } from "@/server/jobs/types";

/** How many organizations one page of the sweep reads. */
const ORG_BATCH = 50;
''')
rep('''/**
 * Issues already announced this process's lifetime. A later sweep still
 * finds a still-open, still-overdue issue — this is what keeps the job from
 * re-emitting `issue.overdue` for it on every pass.
 */
const reported = new Set<string>();

/** Test-only: clears the reported set so a fresh scenario starts empty. */
export function resetOverdueTracking(): void {
  reported.clear();
}
''','''/**
 * Issues the previous sweep found overdue. An issue in this set was already
 * announced and is still overdue, so it is not announced again. An issue a
 * sweep finds not overdue (closed, archived, or due later) drops out of the
 * set, so the next time it is overdue it is announced again.
 */
let overdueLastSweep = new Set<string>();

/** Test-only: forgets the previous sweep so a fresh scenario starts empty. */
export function resetOverdueTracking(): void {
  overdueLastSweep = new Set<string>();
}
''')
rep('''    const stamp = toIsoTimestamp(now);
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);

      for (const issue of overdue) {
        if (issue.dueAt === null) continue;
        if (reported.has(issue.id)) continue;

        try {
          await emit("issue.overdue", {
            orgId,
            actorId: null,
            occurredAt: stamp,
            issueId: issue.id,
            projectId: issue.projectId,
            dueAt: issue.dueAt,
            assigneeId: issue.assigneeId,
          });
          reported.add(issue.id);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to announce overdue issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });''','''    const stamp = toIsoTimestamp(now);
    const previous = overdueLastSweep;
    const current = new Set<string>();

    let afterId: OrgId | null = null;
    for (;;) {
      const orgIds = await orgRepo.listLiveOrgIds(afterId, ORG_BATCH);

      for (const orgId of orgIds) {
        const overdue = await issueRepo.listOverdueIssues(orgId, stamp);

        for (const issue of overdue) {
          if (issue.dueAt === null) continue;

          if (previous.has(issue.id)) {
            current.add(issue.id);
            continue;
          }

          try {
            await emit("issue.overdue", {
              orgId,
              actorId: null,
              occurredAt: stamp,
              issueId: issue.id,
              projectId: issue.projectId,
              dueAt: issue.dueAt,
              assigneeId: issue.assigneeId,
            });
            current.add(issue.id);
            result.processed += 1;
          } catch (error) {
            result.failed += 1;
            logger.error("failed to announce overdue issue", {
              issueId: issue.id,
              reason: error instanceof Error ? error.message : String(error),
            });
          }
        }
      }

      if (orgIds.length < ORG_BATCH) break;
      afterId = orgIds[orgIds.length - 1];
    }

    overdueLastSweep = current;
  });''')
open(p,'w').write(s)
EOF
grep -n "LIVE_ONLY\|shouldFilterArchived" src/server/jobs/overdue-issue-job.ts

